param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$ExpectedSid)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$out=Join-Path $Root 'results';$report=@{status='running';named_fields=@();scope='Exact installed Windows optional folder/default integration, native ShellExecute dispatch, GUI Services and supported uninstall restoration';cases=@()};$final='failed native folder integration audit';$owned=[Collections.Generic.List[Diagnostics.Process]]::new();$forms=[Collections.Generic.List[object]]::new();$install=$null
function Require($value,$message){if(-not$value){throw $message}}
function Save{$p=Join-Path $out 'RESULT.json';$tmp=$p+'.next';[IO.File]::WriteAllText($tmp,($report|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false));if(Test-Path $p){[IO.File]::Replace($tmp,$p,[NullString]::Value)}else{[IO.File]::Move($tmp,$p)}}
function Phase($value){$report.phase=$value;Save}
function Run($exe,$arguments,$name){
 $s=[Diagnostics.ProcessStartInfo]::new($exe,$arguments);$s.UseShellExecute=$false;$s.CreateNoWindow=$true;$s.RedirectStandardOutput=$true;$s.RedirectStandardError=$true;$clock=[Diagnostics.Stopwatch]::StartNew();$p=[Diagnostics.Process]::Start($s)
 try{
  $stdout=$p.StandardOutput.ReadToEndAsync();$stderr=$p.StandardError.ReadToEndAsync()
  if(-not$p.WaitForExit(180000)){
   $snapshot=@(Get-CimInstance Win32_Process|Where-Object {$_.ProcessId-eq$p.Id-or$_.ParentProcessId-eq$p.Id-or($install-and$_.ExecutablePath-and$_.ExecutablePath.StartsWith($install,[StringComparison]::OrdinalIgnoreCase))}|Select-Object Name,ProcessId,ParentProcessId,ExecutablePath,SessionId)
   [IO.File]::WriteAllText((Join-Path $out ($name+'-timeout.json')),(@{seconds=$clock.Elapsed.TotalSeconds;root_pid=$p.Id;processes=$snapshot}|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));throw ('Owned process timeout '+$name)
  }
  Require ($stdout.Wait(5000)-and$stderr.Wait(5000)) 'Process streams not complete';$v=@{exit=$p.ExitCode;stdout=$stdout.Result;stderr=$stderr.Result;seconds=$clock.Elapsed.TotalSeconds};[IO.File]::WriteAllText((Join-Path $out ($name+'-process.json')),($v|ConvertTo-Json),[Text.UTF8Encoding]::new($false));Require ($v.exit-eq0) ('Native child failed '+$name);return $v
 }finally{if(-not$p.HasExited){& "$env:SystemRoot\System32\taskkill.exe" /PID $p.Id /T /F|Out-Null;$null=$p.WaitForExit(10000)};$p.Dispose()}
}
& ([ScriptBlock]::Create([IO.File]::ReadAllText((Join-Path $Root 'native-controls.ps1'))));[PickerNative]::Init()
Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes
function Pump{[Windows.Forms.Application]::DoEvents();Start-Sleep -Milliseconds 50}
function Tree($w){return [Windows.Automation.AutomationElement]::FromHandle($w)}
function Nodes($w,$name){$c=[Windows.Automation.PropertyCondition]::new([Windows.Automation.AutomationElement]::NameProperty,$name);return @((Tree $w).FindAll([Windows.Automation.TreeScope]::Descendants,$c)|Where-Object {-not$_.Current.IsOffscreen})}
function Node($w,$name,$kind){$deadline=[DateTime]::UtcNow.AddSeconds(20);do{$n=@(Nodes $w $name|Where-Object {$_.Current.ControlType-eq$kind});if($n.Count-eq1){return $n[0]};Pump}while([DateTime]::UtcNow-lt$deadline);[PickerNative]::Shot($w,(Join-Path $out 'missing-control.png'));$tree=@((Tree $w).FindAll([Windows.Automation.TreeScope]::Descendants,[Windows.Automation.Condition]::TrueCondition)|ForEach-Object {@{name=$_.Current.Name;role=$_.Current.ControlType.ProgrammaticName;offscreen=$_.Current.IsOffscreen}});[IO.File]::WriteAllText((Join-Path $out 'missing-control-tree.json'),($tree|ConvertTo-Json -Depth 6));throw ('Missing unique '+$name+' count='+$n.Count)}
function Invoke($w,$name){$n=Node $w $name ([Windows.Automation.ControlType]::Button);$n.GetCurrentPattern([Windows.Automation.InvokePattern]::Pattern).Invoke();Pump}
function Key($w,$key){[PickerNative]::Focus($w);[Windows.Forms.SendKeys]::SendWait($key);Start-Sleep -Milliseconds 300;Pump}
function Field($w,$name){$n=Node $w $name ([Windows.Automation.ControlType]::Edit);$v=$n.GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern).Current;return @{name=$n.Current.Name;value=$v.Value;read_only=$v.IsReadOnly;role='Edit'}}
Add-Type -TypeDefinition @'
using System;using System.Runtime.InteropServices;using System.ComponentModel;using Microsoft.Win32;
public static class FolderDispatch {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]public struct Info{public uint size,mask;public IntPtr hwnd;public string verb,file,parameters,directory;public int show;public IntPtr instance,idList;public string klass;public IntPtr key;public uint hotkey;public IntPtr icon,process;}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool ShellExecuteExW(ref Info value);
 [DllImport("kernel32.dll")]static extern uint GetProcessId(IntPtr process);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
 public static int Launch(string target,string verb,string className){if(String.IsNullOrEmpty(verb))verb=null;if(String.IsNullOrEmpty(className))className=null;using(var key=className==null?null:Registry.ClassesRoot.OpenSubKey(className)){var i=new Info();i.size=(uint)Marshal.SizeOf(i);i.mask=0x40|0x100|0x400;i.verb=verb;i.file=target;i.directory=target;i.show=1;if(className!=null){if(key==null)throw new Exception("Missing merged shell class");i.mask|=3;i.key=key.Handle.DangerousGetHandle();}if(!ShellExecuteExW(ref i))throw new Win32Exception(Marshal.GetLastWin32Error());if(i.process==IntPtr.Zero)throw new Exception("Missing child handle");try{return (int)GetProcessId(i.process);}finally{CloseHandle(i.process);}}}
}
'@
function DefaultSnapshot{
 $v=[ordered]@{};foreach($path in @('Software\Classes\Directory\shell','Software\Classes\Directory\Background\shell','Software\Classes\Drive\shell')){
  $k=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($path);try{$exists=$k-and(''-in$k.GetValueNames());$v[$path]=[ordered]@{exists=[bool]$exists;kind=$(if($exists){$k.GetValueKind('').ToString()}else{''});value=$(if($exists){$k.GetValue('',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)}else{$null})}}finally{if($k){$k.Dispose()}}
 };return ($v|ConvertTo-Json -Depth 12 -Compress)
}
function FolderJson($arguments,$name){$v=Run $app $arguments $name;return ($v.stdout|ConvertFrom-Json)}
function Window($p,$title){$deadline=[DateTime]::UtcNow.AddSeconds(25);do{$w=[PickerNative]::Window($p.Id,$title);if($w-ne[IntPtr]::Zero){[PickerNative]::Place($w);[PickerNative]::Focus($w);return $w};Pump}while([DateTime]::UtcNow-lt$deadline);throw ('Missing owned window '+$title)}
function CloseMain($p,$w){Invoke $w 'Close window';Require ($p.WaitForExit(15000)-and$p.ExitCode-eq0) 'Normal native main close failed'}
function FindFolderAction($w,$name){for($i=0;$i-lt12;$i++){if(@(Nodes $w $name).Count-eq1){return};[PickerNative]::Wheel($w,-600);Start-Sleep -Milliseconds 180};throw ('Folder action not visible '+$name)}
function StatusUntil($key,$expected){$deadline=[DateTime]::UtcNow.AddSeconds(15);do{$s=FolderJson 'folders status --json' ('status-'+[Guid]::NewGuid().ToString('N'));if($s.$key-eq$expected){return $s};Pump}while([DateTime]::UtcNow-lt$deadline);throw ('Folder status did not reach '+$key+'='+$expected)}
function Dispatch($case,$target,$verb,$className){
 $pidValue=[FolderDispatch]::Launch($target,$verb,$className);$p=Get-Process -Id $pidValue;$null=$p.Handle;$owned.Add($p);$deadline=[DateTime]::UtcNow.AddSeconds(10);$imagePath=$null;do{$p.Refresh();try{$imagePath=$p.MainModule.FileName}catch{};if($imagePath-or$p.HasExited){break};Pump}while([DateTime]::UtcNow-lt$deadline);$nativeProcess=Get-CimInstance Win32_Process -Filter ("ProcessId="+$pidValue);$dispatchIdentity=@{case=$case;pid=$pidValue;expected=$app;loaded_image=$imagePath;native_image=$nativeProcess.ExecutablePath;command=$nativeProcess.CommandLine;exited=$p.HasExited};[IO.File]::WriteAllText((Join-Path $out ($case+'-identity.json')),($dispatchIdentity|ConvertTo-Json));Require ($imagePath-ieq$app) ('Shell launched an unexpected or unavailable program; observed image='+$imagePath);$w=Window $p 'Ottrin';Key $w '^l';$f=Field $w 'Location';$expected='\\?\'+$target;Require ($f.value-ieq$expected) ('Shell dispatch opened wrong location: '+$f.value+' expected '+$expected);[PickerNative]::Shot($w,(Join-Path $out ($case+'-location.png')));Key $w '{ESC}';$command=(Get-CimInstance Win32_Process -Filter "ProcessId=$pidValue").CommandLine;CloseMain $p $w;$report.cases+=@{case=$case;requested=$target;verb=$verb;merged_class=$className;native_location=$f.value;command_line=$command;executable=$app;exit=$p.ExitCode};Save
}
try{
 Require ([Security.Principal.WindowsIdentity]::GetCurrent().User.Value-eq$ExpectedSid) 'Wrong owned account';Require (-not([Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) 'Must be ordinary user'
 $identity=Get-Content (Join-Path $Root 'application-input.json') -Raw|ConvertFrom-Json;foreach($file in $identity.files){Require ((Get-FileHash (Join-Path $Root $file.name)).Hash.ToLowerInvariant()-eq$file.sha256) 'Input mismatch'};$report.package=$identity;$report.powershell_cli_alias=(Get-Alias cli -ErrorAction SilentlyContinue).Definition
 $manifest=Get-Content (Join-Path $Root 'payload.json') -Raw|ConvertFrom-Json;$install=Join-Path $env:LOCALAPPDATA 'Programs\Ottrin';$app=Join-Path $install 'bin\ottrin.exe';Require (-not(Test-Path $install)) 'Existing install retained'
 Phase 'install exact current NSIS';$null=Run (Join-Path $Root 'current-setup.exe') '/S' 'install';foreach($f in $manifest.PSObject.Properties){Require ((Get-FileHash (Join-Path $install $f.Name)).Hash.ToLowerInvariant()-eq$f.Value) ('Payload mismatch '+$f.Name)};$report.payload_files=58
 $null=Run $app 'index service-remove' 'index-remove';Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Unexpected index process';$before=FolderJson 'folders status --json' 'baseline-status';Require (-not$before.enabled-and-not$before.default_enabled) 'Existing folder registration retained';$baseline=DefaultSnapshot;$report.default_baseline=$baseline
 $corpus=Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'Ottrin folders %1 100% literal';Require (-not(Test-Path $corpus)) 'Existing corpus retained';$null=[IO.Directory]::CreateDirectory($corpus);$source=Join-Path $corpus 'preserve.txt';[IO.File]::WriteAllText($source,'owned integration original',[Text.UTF8Encoding]::new($false));$original=(Get-FileHash $source).Hash
 $config=Get-Content (Join-Path $Root 'config-template.json') -Raw|ConvertFrom-Json;$config.bookmarks=@();$config.theme='Dark';$config.default_view_mode='List';$config.graphics_renderer='Native';$config.search.include_roots=@($corpus);$config.search.content_indexing_enabled=$false;$pref=Join-Path $env:APPDATA 'ottrin\config.json';Require (-not(Test-Path $pref)) 'Existing preferences retained';$null=[IO.Directory]::CreateDirectory((Split-Path $pref));[IO.File]::WriteAllText($pref,($config|ConvertTo-Json -Depth 30),[Text.UTF8Encoding]::new($false))
 $null=Run $app 'folders enable' 'enable-menu';$s=FolderJson 'folders status --json' 'menu-status';Require ($s.enabled-and$s.ready-and-not$s.default_enabled) 'Menu setup status wrong';Require ((DefaultSnapshot)-eq$baseline) 'Menu setup altered defaults';Require (@(Get-Process ottrin-indexd -ErrorAction SilentlyContinue).Count-eq0) 'Folder CLI started indexing'
 Phase 'actual merged menu verbs';Dispatch 'directory-verb' $corpus 'Ottrin.Open' 'Directory';Dispatch 'background-verb' $corpus 'Ottrin.Open' 'Directory\Background';Dispatch 'drive-verb' 'C:\' 'Ottrin.Open' 'Drive'
 $start=[Diagnostics.ProcessStartInfo]::new($app,('"'+$corpus+'"'));$start.UseShellExecute=$false;$main=[Diagnostics.Process]::Start($start);$owned.Add($main);$w=Window $main 'Ottrin';Invoke $w 'Menu';Invoke $w ('Settings'+[char]0x2026);$settings=Window $main 'Ottrin Settings';[PickerNative]::Shot($settings,(Join-Path $out 'settings-before-services.png'));[PickerNative]::Click($settings,78,202);Pump;$report.services_navigation=@{method='native pointer at directly reviewed 920x640 screenshot row';logical_x=78;logical_y=202;limitation='Custom painted Settings navigation has no named accessibility node in this package'};FindFolderAction $settings 'Use Ottrin to open folders';[PickerNative]::Shot($settings,(Join-Path $out 'services-default-off.png'));Invoke $settings 'Use Ottrin to open folders';$s=StatusUntil 'default_ready' $true;Require ($s.ready-and$s.default_enabled) 'GUI default setup not ready';[PickerNative]::Shot($settings,(Join-Path $out 'services-default-on.png'));$report.gui_enabled=$s
 Phase 'default Windows folder dispatch';Dispatch 'default-directory' $corpus $null $null;Dispatch 'default-drive' 'C:\' $null $null
 $null=Run $app 'folders enable' 'repair-menu';$s=FolderJson 'folders status --json' 'repair-status';Require ($s.default_ready-and$s.default_enabled) 'Repair lost default choice';$report.repair_preserved_default=$true
 FindFolderAction $settings 'Restore previous folder defaults';Invoke $settings 'Restore previous folder defaults';$s=StatusUntil 'default_enabled' $false;Require ((DefaultSnapshot)-eq$baseline) 'GUI restore changed original typed defaults';$report.gui_restored_defaults=$true;Invoke $settings 'Close window';CloseMain $main $w
 Phase 'preserve later user choice on supported uninstall';$null=Run $app 'folders default-enable' 'default-enable-again';$s=FolderJson 'folders status --json' 'pre-uninstall-status';Require ($s.default_ready) 'Default re-enable failed'
 $key=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Classes\Directory\shell',$true);try{$key.SetValue('','open',[Microsoft.Win32.RegistryValueKind]::String);$key.SetValue('OttrinAuditForeignMarker',$identity.actor_sha256,[Microsoft.Win32.RegistryValueKind]::String)}finally{$key.Dispose()};$s=FolderJson 'folders status --json' 'later-choice-status';Require ($s.default_enabled-and-not$s.default_ready) 'Later choice not reported honestly';$report.later_choice_status=$s
 $prefHash=(Get-FileHash $pref).Hash;$uninstaller=Join-Path $out 'owned-uninstall.exe';Copy-Item (Join-Path $install 'Uninstall.exe') $uninstaller;$null=Run $uninstaller ('/S _?='+$install) 'uninstall';Remove-Item $uninstaller;Require (-not(Test-Path $install)) 'Uninstall left application files';Require ((Get-FileHash $pref).Hash-eq$prefHash-and(Get-FileHash $source).Hash-eq$original) 'Preferences/source changed by removal'
 $after=DefaultSnapshot;$expected=$baseline|ConvertFrom-Json;$expected.'Software\Classes\Directory\shell'.exists=$true;$expected.'Software\Classes\Directory\shell'.kind='String';$expected.'Software\Classes\Directory\shell'.value='open';$actual=$after|ConvertFrom-Json
 foreach($path in @('Software\Classes\Directory\shell','Software\Classes\Directory\Background\shell','Software\Classes\Drive\shell')){Require (($actual.$path|ConvertTo-Json -Compress)-eq($expected.$path|ConvertTo-Json -Compress)) ('Unexpected default after removal '+$path)}
 $key=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Classes\Directory\shell');try{Require ($key.GetValue('OttrinAuditForeignMarker')-eq$identity.actor_sha256) 'Unrelated registry data removed'}finally{$key.Dispose()}
 foreach($path in @('Directory','Directory\Background','Drive')){Require ($null-eq[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey(('Software\Classes\'+$path+'\shell\Ottrin.Open'))) 'Owned menu verb remained'};Require ($null-eq[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Ottrin\DesktopIntegration')) 'Owned receipt remained'
 $report.uninstall_restored_owned_defaults=$true;$report.later_choice_preserved=$true;$report.unrelated_registry_data_preserved=$true;$report.source_and_preferences_preserved=$true;$report.defaults_after=$after;$final='pass current installed optional folder integration scope; originals require review'
}catch{$report.error=$_.Exception.Message;$report.stack=$_.ScriptStackTrace}
finally{
 foreach($p in $owned){if(-not$p.HasExited){& "$env:SystemRoot\System32\taskkill.exe" /PID $p.Id /T /F|Out-Null;$null=$p.WaitForExit(10000)}}
 if($install-and(Test-Path $app)-and$manifest-and(Get-FileHash $app).Hash.ToLowerInvariant()-eq$manifest.'bin/ottrin.exe'){try{$report.cleanup_folders=Run $app 'folders disable' 'cleanup-folders';$report.cleanup_index=Run $app 'index service-remove' 'cleanup-index'}catch{$report.cleanup_error=$_.Exception.Message;$final='failed owned integration cleanup'}}
 if($install){$left=@(Get-CimInstance Win32_Process|Where-Object {$_.ExecutablePath-and$_.ExecutablePath.StartsWith($install,[StringComparison]::OrdinalIgnoreCase)});$report.remaining_owned_installed_processes=$left.Count;if($left.Count){$final='failed owned process cleanup'}}
 $report.status=$final;Save
}
if(-not$final.StartsWith('pass')){exit 1}
